import re

items_out = []

for item in items:
    data = item.get("json", {})

    # Берём текст из возможных полей
    text = (
        data.get("text")
        or data.get("message")
        or data.get("content")
        or ""
    )

    # Ищем телефон в русском формате
    match = re.search(r'(?:\+7|8)\s*\(?\d{3}\)?[\s-]?\d{3}[\s-]?\d{2}[\s-]?\d{2}', text)

    if not match:
        # если не нашли — возвращаем флаг
        items_out.append({
            "json": {
                "hasPhone": False,
                "originalText": text,
            }
        })
    else:
        # match.group(0) — найденный кусок
        clean = re.sub(r'[^\d+]', '', match.group(0))

        items_out.append({
            "json": {
                "hasPhone": True,
                "phone": clean,
                "originalText": text,
            }
        })

# n8n в Python-узле ожидает вернуть список items
return items_out

