// Берём текст сообщения
const text =  $input.first().json.userText || "";

// Ищем телефон в русском формате
const match = text.match(/(\+7|8|\+375|375|7)\s*\(?(?:\d{2,3})\)?[\s-]?\d{3}[\s-]?\d{2}[\s-]?\d{2}/);

if (!match) {
  // если не нашли — можно вернуть флаг
  return [{
    hasPhone: false,
    originalText: text,
  }];
}

// match[0] — это то, что нашли
// очищаем от пробелов и скобок
const clean = match[0].replace(/[^\d+]/g, '');

return [{
  hasPhone: true,
  phone: clean,
  originalText: text,
}];

const newItems = [];

for (const item of items) {
  let data = item.json;

  let raw = data.output || data;

  if (typeof raw === 'string') {
    raw = raw.trim();

    // убираем обёртку ```...``` если она есть
    if (raw.startsWith('```')) {
      // убираем первые ```... и последние ```
      raw = raw.replace(/^```[a-zA-Z]*\n?/, '').replace(/```$/, '').trim();
    }

    try {
      raw = JSON.parse(raw);
    } catch (error) {
      raw = { error: 'Ошибка парсинга', raw };
    }
  }

  newItems.push({
    json: {
      id_вопроса: raw.id_вопроса ?? null,
      ответ: raw['Ответ'] ?? $input.first().json.output
    }
  });
}

return newItems;

const newItems = [];

for (const item of items) {
  let data = item.json;

  // если input — строка, парсим
  if (typeof data === 'string') {
    try {
      data = JSON.parse(data);
    } catch (err) {
      // парсинг не удался — продолжаем с тем, что есть
    }
  }

  // ---- photos ----
  const urlPhotoField = data.url_photo;
  let photosObj = {};
  let count_photo = 0;

  if (typeof urlPhotoField === 'string' && urlPhotoField.trim() !== '') {
    const urls = urlPhotoField
      .split(',')
      .map(u => u.trim())
      .filter(Boolean);

    count_photo = urls.length;
    urls.forEach((u, idx) => {
      photosObj[idx + 1] = u;
    });
  }

  // ---- docs (новое) ----
  const urlDocField = data.url_doc;
  let docsObj = {};
  let count_doc = 0;

  if (typeof urlDocField === 'string' && urlDocField.trim() !== '') {
    const urls = urlDocField
      .split(',')
      .map(u => u.trim())
      .filter(Boolean);

    count_doc = urls.length;
    urls.forEach((u, idx) => {
      docsObj[idx + 1] = u;
    });
  }

  // ---- video ----
  const urlVideoField = data.url_video;
  const count_video =
    (typeof urlVideoField === 'string' && urlVideoField.trim().length > 0) ? 1 : 0;

  newItems.push({
    json: {
      id: data.id,
      вопрос: data.вопрос,
      ответ: data.ответ,
      photos: photosObj,
      docs: docsObj,          
      url_video: urlVideoField,
      count_photo: count_photo,
      count_doc: count_doc, 
      count_video: count_video
    }
  });
}

return newItems;
